INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.134.0',
  '2026-11-16',
  'AI — форк сессии: та же история, своя ветка разговора',
  E'AI. У сессии теперь две кнопки вместо одной. «Продолжить» — как раньше: дописывает ту же сессию, и дальше она идёт одной линией. «🍴 Форк» — начинает НОВУЮ сессию с историей старой: агент помнит весь разговор, но исходная сессия остаётся нетронутой, и в ней можно спокойно продолжить своё. Удобно, когда хочется попробовать другой путь, не ломая уже сделанное.\n\nФорк доступен и из открытой задачи — кнопка «🍴 Форкнуть»: папка, модель и параметры берутся те же, а ветка пойдёт отдельной задачей со своей сессией. Исходная задача не меняется, обе видно в списке рядом. У задачи-форка в заголовке 🍴, а под названием видно id новой сессии и id той, от которой она отделилась (нажмите — скопируется).\n\nУ Codex к форку есть галочка «🌿 в отдельном git-worktree»: правки форка идут не в рабочее дерево папки, а в отдельную копию (Codex создаёт её в ~/.codex/worktrees/) — в результате прогона показан путь, где они лежат. У Claude Code такого флага нет: там форк только по сессии, файлы правятся в той же папке.\n\nПод капотом это ровно то, что делают сами инструменты: claude --resume <id> --fork-session и codex exec fork <id> [--worktree].',
  E'Миграция 0194: ai_runs.fork и ai_runs.worktree (флаги живут на ПРОГОНЕ, как mode: прогон может ждать в очереди при офлайне и уходить агенту позже, значит чем он был — должно храниться; QueuedAIRun и deliverQueued их возят), ai_tasks.forked_from (новый session_id приедет с результатом первого прогона и перепишет session_id задачи — без этого поля было бы не видно, от какой сессии ветка отделилась).\n\nФорк — всегда НОВАЯ задача, а не прогон в текущей: смысл форка — ветка, и обе ветки должны остаться видимыми рядом. Поэтому отдельного эндпоинта нет: POST /ai/tasks принимает fork + session_id (и worktree), заголовок получает префикс 🍴 вместо ↩. Проверки: fork без session_id — 400 (форкать нечего), worktree без fork — 400, worktree у claude — 400 (флага нет у инструмента). Продолжение задачи (POST /ai/tasks/{id}/runs) форк не принимает сознательно — иначе задача незаметно уехала бы в другую сессию.\n\nАгент v1.9.0: сборка командной строки вынесена из executeClaude/executeCodex в claudeArgs/codexArgs — флаги это и есть фича, их проверяет unit-тест, а не только живой запуск. claude: --resume <id> --fork-session; --fork-session в доп. параметрах теперь фильтруется, как --resume. codex: форк — ОТДЕЛЬНАЯ подкоманда `codex exec fork <id>` (не флаг к resume), --worktree добавляется только к форку и только если его не задали руками (hasArg). Новый session_id приходит обычным путём (result.session_id у claude, thread.started у codex), FinishAIRun кладёт его в задачу — продолжение дальше идёт уже по новой сессии.\n\nФорк с --worktree выполняется НЕ в папке задачи, поэтому ветка и git diff --stat снимались бы с чужого дерева. Путь настоящей папки агент берёт из файла новой сессии codex (session_meta.cwd через sessionByID — тот же код, что у «сессий по id») и кладёт в meta.worktree_dir; страница показывает его в прогоне.\n\nПроверено локально НАСТОЯЩИМИ CLI (claude 2.1.325, codex-cli 0.166.0) на одноразовой базе: 28 проверок. Форк claude ушёл с --resume <id> --fork-session, вернул новый id, файл исходной сессии не вырос ни на байт, а обычное продолжение той же сессии — вырос; форк codex ушёл как exec fork <id> --worktree, создал git-worktree (git worktree list его видит), вернул новый thread id, и в meta.worktree_dir оказался путь ~/.codex/worktrees/<n>/repo. Плюс unit-тесты на сборку аргументов (план+форк, форк без сессии, дубль --worktree) и три отказа валидации.'
);
